int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    while (i < fromlen) {
        if (tolen <= j) {
            return -ENAMETOOLONG;
        }

        unsigned char type = from[i];
        switch (type) {
            case 0x00: // symlink
                if (j > 0) {
                    to[j++] = '/';
                }
                i++;
                while (i < fromlen && j < tolen) {
                    to[j++] = from[i++];
                }
                break;
            case 0x01: // directory indicator
                if (j > 0) {
                    to[j++] = '/';
                }
                to[j++] = '.';
                i++;
                break;
            case 0x02: // filename
                while (i < fromlen && from[i] != '\0') {
                    if (j >= tolen) {
                        return -ENAMETOOLONG;
                    }
                    to[j++] = from[i++];
                }
                i++;
                break;
            default:
                return -EINVAL;
        }
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

int path_component_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int pos = 0;

    while (i < fromlen) {
        unsigned char type = from[i];

        if (type == 0) {
            if (pos < tolen) {
                to[pos++] = '.';
            }
            if (pos < tolen) {
                to[pos++] = '.';
            }
        } else if (type == 1) {
            if (pos < tolen) {
                to[pos++] = '.';
            }
        } else if (type == 2) {
            int j = 0;
            while (i + 1 + j < fromlen && j < tolen - pos) {
                to[pos++] = from[i + 1 + j];
                j++;
            }
        } else {
            return -EINVAL;
        }

        i += (type == 0 || type == 1) ? 1 : 1 + (from[i + 1] + 1);
    }

    if (pos < tolen) {
        to[pos] = '\0';
    } else {
        return -ENAMETOOLONG;
    }

    return 0;
}

int path_to_string(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i, j = 0;
    for (i = 0; i < fromlen; i++) {
        if (j >= tolen - 1) {
            return -ENAMETOOLONG;
        }

        if (from[i] == '/') {
            to[j++] = '/';
            continue;
        } else if (from[i] == '.') {
            if (i + 1 < fromlen && from[i + 1] == '/') {
                i++;
                continue;
            }
        } else if (from[i] == '@') {
            if (i + 1 < fromlen) {
                i++;
                continue;
            }
        } else {
            to[j++] = from[i];
        }
    }

    if (j >= tolen) {
        return -ENAMETOOLONG;
    }

    to[j] = '\0';
    return 0;
}

int path_from_path(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i = 0;
    int j = 0;

    while (i < fromlen && j < tolen - 1) {
        if (from[i] == 0) {
            to[j++] = '.';
            i++;
        } else if (from[i] == 1) {
            to[j++] = '.';
            to[j++] = '.';
            i++;
        } else if (from[i] >= 2 && from[i] <= 255) {
            int len = from[i];
            i++;
            while (len > 0 && j < tolen - 1) {
                to[j++] = from[i];
                i++;
                len--;
            }
        } else {
            return -1;
        }
    }

    if (i < fromlen) {
        return -1;
    }

    if (j >= tolen) {
        return -1;
    }

    to[j] = '\0';
    return 0;
}

int path_to_char(struct super_block *sb, unsigned char *from, int fromlen, unsigned char *to, int tolen) {
    int i;
    int pos = 0;

    for (i = 0; i < fromlen; i++) {
        unsigned char type = from[i];

        if (type == 0) {
            continue;
        }

        if (type == '/') {
            if (pos >= tolen) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '/';
        } else if (type == '.') {
            if (pos + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[pos++] = '.';
            to[pos++] = '/';
        } else if (type == '@') {
            if (pos + 2 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[pos++] = 's';
            to[pos++] = 'y';
            to[pos++] = 'm';
        } else {
            if (pos + 1 >= tolen) {
                return -ENAMETOOLONG;
            }
            to[pos++] = 'f';
            to[pos++] = type;
        }
    }

    if (pos >= tolen) {
        return -ENAMETOOLONG;
    }
    to[pos] = '\0';
    return 0;
}
